<script lang="ts">import type { PageProps } from './$types'; import { Badge, Card, Icon, i18n } from '$lib'; let { data }: PageProps = $props(); const money = (v: string) => new Intl.NumberFormat(i18n.locale,{style:'currency',currency:'PEN'}).format(Number(v));</script>
<Card padding="none"><div class="border-b border-hairline px-5 py-4"><h2 class="text-lg font-semibold text-ink">{i18n.t('pets.tabPurchases')}</h2><p class="mt-1 text-sm text-steel">{i18n.t('pets.purchasesHelp')}</p></div>{#if data.mascota.ventas.length}<div class="divide-y divide-hairline">{#each data.mascota.ventas as sale}<article class="grid gap-4 px-5 py-4 md:grid-cols-[130px_minmax(0,1fr)_140px]"><div><span class="text-xs text-stone">#{sale.numero}</span><strong class="mt-1 block text-sm text-ink">{new Intl.DateTimeFormat(i18n.locale,{dateStyle:'medium'}).format(new Date(sale.created_at))}</strong></div><div class="min-w-0"><div class="flex flex-wrap gap-2">{#each sale.detalles as detail}<Badge variant="outline-sky">{detail.descripcion} · {detail.cantidad}</Badge>{/each}</div></div><div class="text-left md:text-right"><strong class="block text-base text-ink">{money(sale.total)}</strong><span class="text-xs text-stone">{sale.estado_venta.etiqueta}</span></div></article>{/each}</div>{:else}<div class="grid place-items-center px-5 py-14 text-center"><Icon name="shopping-bag" size={32} class="text-stone"/><p class="mt-3 text-sm text-steel">{i18n.t('pets.noPurchases')}</p></div>{/if}</Card>
